var fix = this._menuFixados();
var marcado = function (id) { return !fix || fix.indexOf(id) > -1; };
var corpo = '<p class="muted" style="margin:0 0 10px">Marque o que você usa no dia a dia — fica sempre à vista na barra lateral. '
