var ob = g.obra ? (Store.obter(eid(), "obras", g.obra) || {}) : {};
g.arquivo = window.BimProjetos ? BimProjetos.nomePadrao(g.nome, ob.nome || "") : (g.nome || "Projeto");
var el = document.querySelector('#modal-bg [data-np="arquivo"]');
