'<div class="b4h-s">' + Util.esc(sub.join(" · ")) + "</div>" +
(ativas.length ? '<div class="b4h-a">' + ativas.map(function (x) { return Util.esc(x); }).join("<br>") + (est.ativas.length > 3 ? "<br>+ " + (est.ativas.length - 3) + " etapa(s)" : "") + "</div>" : "");
