var jaRegistrado = Util.arr(pc.recebimentos).reduce(function (s, v) { return s + Util.num(v && v.valor); }, 0);
var vivasPC = temMotorNota ? CompraNota.despesasDaCompra(listaTodas("financeiro"), pc.id) : [];
