afterRender: function (view) { if (this._trancadoModela && this._trancadoModela(view)) return; if (typeof Carregar !== "undefined" && Carregar.faltaPara && Carregar.faltaPara(view)) return; if (this._wiresExtras && this._wiresExtras[view]) { try { this._wiresExtras[view].call(this); } catch (eW) {} } if (view === "producao") this.afterRenderProducao(); else if (view === "fiscal") this._triWire(); else if (view === "insumos") this._wireBancoView(); else if (view === "epi") this.afterRenderEpi(); else if (view === "ponto") this.afterRenderPonto(); else if (view === "galeria") this._galeriaWire(); else if (view === "ajuda") this._ajudaWire(); else if (view === "bim") this._bimWire(); else if (view === "lastplanner") this._lpWire(); },
