Util.arr(ob.ctx.ccsCrus).forEach(function (c) { if (c && String(c.id) === String(fa.cc)) ccF = c; });
if (!(ccF && String(ccF.obraId || "") === o)) return self._ccRotuloDeFora(ccF, fa.cc);
