Util.arr(ac.financeiro).forEach(function (f) { if (f && String(f.id) === e.id) fr = f; });
var cpN = fr && fr.compraId ? cpPorId[String(fr.compraId)] : null;
viaCc = !!(cpN && cpN.ccId);
