var vNovoE = Util.num(lancE && lancE.valor), vFinE = Math.abs(Util.num(vivoE.valor));
var difValor = Math.abs(vNovoE - vFinE) >= 0.005;
var obraDoc = String((obj && obj.obraId) || ""), obraFin = String(vivoE.obraId || "");
