if (id) {
var p = Store.obter(eid(), ENT_PROP, id);
if (p && !C.estaFechada(p)) {
coletar(p, C.calcular(p, ctx()));
Store.salvar(eid(), ENT_PROP, p);
}
}
this._carpProp = null;
App.render();
