UI.fecharModal();
var rot = null;
CronoExecUI.DOCS.forEach(function (x) { if (x.id === tipo) rot = x.nome; });
this._abrirPrint((rot || "Documento") + (nomeObra ? " — " + nomeObra : ""), html, "relatorio");
