UI.toast(fdc.length + " informação(ões) não entraram neste documento: " +
fdc.slice(0, 2).map(function (x) { return String((x && x.msg) || x); }).join(" · ") +
(fdc.length > 2 ? " (e mais " + (fdc.length - 2) + ")" : ""), "");
