var linhas = (matriz || []).filter(function (r) { return r && r.some(function (c) { return String(c == null ? "" : c).trim() !== ""; }); });
if (!linhas.length) return [];
var nCols = 0; linhas.forEach(function (r) { if (r.length > nCols) nCols = r.length; });
