if (!n || n.realPct == null) return;
var manda = execR ? (n.folha === true) : (n.tipo === "etapa");
if (!manda) return;
real[n.id] = { p: n.realPct, i: (n.real && n.real.ini) || null, f: (n.real && n.real.fim) || null };
