UI.modal("Fixe o início da obra", '<p>' + Util.esc(r.erro) + '</p>' + this._cronoPortaInicioHtml({ tipo: "plano", obra: c.obra }, null, "Fixe o início e lance de novo:"),
[{ texto: "Fechar", classe: "ghost", onClick: function () { UI.fecharModal(); } }]);
